 import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  color,
  mix,
  smoothstep,
  oneMinus,
  texture,
  uniform,
  fract,
  sin,
  dot,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const atlas = config.intent?.visualSpec?.atlas ?? config.atlasRegion ?? {};
  const [sx = 0, sy = 0, sw = 512, sh = 320] = Array.isArray(atlas.sourceRect)
    ? atlas.sourceRect
    : [0, 0, 512, 320];

  const pxPerUnit = 200;
  const width = sw / pxPerUnit;
  const height = sh / pxPerUnit;

  const geometry = new ctx.THREE.PlaneGeometry(width, height);

  const placeholder = new ctx.THREE.DataTexture(
    new Uint8Array([22, 22, 29, 255]),
    1,
    1
  );
  placeholder.needsUpdate = true;

  const texUniform = uniform(placeholder);
  const texNode = texture(texUniform, uv());

  const uvy = uv().y;
  const grad = mix(color(ink), color(surface), smoothstep(0, 1, uvy));
  const topEdge = oneMinus(smoothstep(0, 0.02, uvy));
  const gradAccent = mix(grad, color(accent), topEdge.mul(0.9));

  const metal = texNode.rgb;
  const base = mix(gradAccent, metal, 0.22);

  const noise = fract(
    sin(dot(uv(), vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grain = noise.sub(0.5).mul(0.03);
  const finalColor = base.add(vec3(grain));

  const material = new MeshBasicNodeMaterial({
    colorNode: finalColor,
  });

  const plane = new ctx.THREE.Mesh(geometry, material);
  group.add(plane);

  const textItems =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    if (!item?.text) continue;
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: paper,
      align: 'center',
      maxWidthPx: sw * 0.85,
      letterSpacingPx: 0,
    });
    textObj.position.z = 0.03;
    group.add(textObj);
  }

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        tex.colorSpace = ctx.THREE.SRGBColorSpace;
        tex.needsUpdate = true;
        texUniform.value = tex;
        material.needsUpdate = true;
      })
      .catch(() => {});
  }

  const timelines = [];
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      try {
        tl.kill();
      } catch (e) {}
    });
    group.traverse((obj) => {
      if (obj.geometry) {
        try {
          obj.geometry.dispose();
        } catch (e) {}
      }
      const mats = Array.isArray(obj.material)
        ? obj.material
        : [obj.material];
      mats.forEach((m) => {
        if (m?.dispose) {
          try {
            m.dispose();
          } catch (e) {}
        }
      });
    });
    try {
      placeholder.dispose();
    } catch (e) {}
  };

  return group;
}
